arguments.cmd:
cat > /app/output/index.html <<'EOF'
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Fresh Pantry — Discover Everyday Deliciousness</title>
  <meta name="description" content="Fresh Pantry is your neighborhood grocery destination for unique, high-quality products at great prices." />
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Nunito:wght@600;700;800&family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
  <style>
    :root {
      --bg: oklch(0.98 0.02 104);
      --surface: oklch(0.995 0.008 95);
      --surface-2: oklch(0.97 0.02 102);
      --text: oklch(0.31 0.04 145);
      --muted: oklch(0.5 0.03 145);
      --primary: oklch(0.68 0.14 145);
      --primary-deep: oklch(0.56 0.14 146);
      --accent: oklch(0.84 0.14 85);
      --accent-2: oklch(0.74 0.14 42);
      --border: oklch(0.89 0.02 110);
      --shadow: 0 10px 30px color-mix(in oklch, var(--primary-deep) 10%, transparent);
      --shadow-soft: 0 8px 20px color-mix(in oklch, black 8%, transparent);
      --radius-lg: 1.25rem;
      --radius-md: 0.9rem;
      --container: min(1120px, calc(100% - 2rem));
    }

    * { box-sizing: border-box; }
    html { scroll-behavior: smooth; }
    body {
      margin: 0;
      font-family: "Inter", system-ui, -apple-system, sans-serif;
      color: var(--text);
      background: linear-gradient(180deg, var(--bg) 0%, oklch(0.965 0.03 110) 100%);
      line-height: 1.5;
    }

    h1, h2, h3, .brand, .nav-link, .btn {
      font-family: "Nunito", "Inter", sans-serif;
      letter-spacing: 0.01em;
    }

    img { max-width: 100%; display: block; }
    a { text-decoration: none; color: inherit; }

    .container { width: var(--container); margin-inline: auto; }
    .section { padding: 4.5rem 0; }
    .section-title {
      font-size: clamp(1.5rem, 2.8vw, 2.2rem);
      margin: 0 0 0.75rem;
      line-height: 1.2;
    }
    .section-subtitle {
      margin: 0;
      color: var(--muted);
      max-width: 65ch;
      font-size: 1.02rem;
    }

    .site-header {
      position: sticky;
      top: 0;
      z-index: 20;
      backdrop-filter: blur(10px);
      background: color-mix(in oklch, var(--surface) 78%, white 22%);
      border-bottom: 1px solid color-mix(in oklch, var(--border) 60%, white 40%);
    }

    .header-inner {
      min-height: 76px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
    }

    .brand {
      font-size: 1.5rem;
      font-weight: 800;
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      color: var(--primary-deep);
    }

    .brand-badge {
      width: 2rem;
      height: 2rem;
      border-radius: 999px;
      display: grid;
      place-items: center;
      background: radial-gradient(circle at 30% 30%, var(--accent), var(--primary));
      color: white;
      font-size: 1rem;
      box-shadow: var(--shadow-soft);
    }

    nav ul {
      margin: 0;
      padding: 0;
      list-style: none;
      display: flex;
      gap: clamp(0.8rem, 2vw, 1.6rem);
      align-items: center;
    }

    .nav-link {
      font-weight: 700;
      font-size: 0.98rem;
      color: color-mix(in oklch, var(--text) 85%, var(--primary-deep) 15%);
      transition: color 180ms ease;
    }
    .nav-link:hover,
    .nav-link:focus-visible { color: var(--primary-deep); }

    .hero-grid {
      display: grid;
      grid-template-columns: 1.1fr 0.9fr;
      gap: clamp(1.4rem, 4vw, 3rem);
      align-items: center;
    }

    .hero-title {
      font-size: clamp(2rem, 5vw, 3.8rem);
      line-height: 1.05;
      margin: 0 0 1rem;
      color: color-mix(in oklch, var(--text) 78%, var(--primary-deep) 22%);
    }

    .hero-copy {
      font-size: 1.08rem;
      color: var(--muted);
      margin-bottom: 1.6rem;
      max-width: 55ch;
    }

    .actions { display: flex; flex-wrap: wrap; gap: 0.8rem; }

    .btn {
      border: 0;
      border-radius: 999px;
      font-weight: 800;
      font-size: 0.98rem;
      padding: 0.78rem 1.2rem;
      cursor: pointer;
      min-height: 44px;
      transition: transform 150ms ease, box-shadow 200ms ease, background 200ms ease;
    }

    .btn:active { transform: scale(0.97); }

    .btn-primary {
      background: linear-gradient(135deg, var(--primary), var(--primary-deep));
      color: white;
      box-shadow: var(--shadow);
    }
    .btn-primary:hover,
    .btn-primary:focus-visible {
      transform: translateY(-2px);
      box-shadow: 0 14px 32px color-mix(in oklch, var(--primary-deep) 18%, transparent);
    }

    .btn-secondary {
      background: var(--surface);
      color: var(--primary-deep);
      border: 1px solid var(--border);
    }

    .hero-card {
      border-radius: var(--radius-lg);
      overflow: hidden;
      background: var(--surface);
      box-shadow: var(--shadow-soft);
      border: 1px solid var(--border);
      position: relative;
    }

    .hero-card img {
      width: 100%;
      aspect-ratio: 4/5;
      object-fit: cover;
    }

    .hero-chip {
      position: absolute;
      bottom: 1rem;
      left: 1rem;
      background: color-mix(in oklch, var(--surface) 75%, white 25%);
      color: var(--text);
      border: 1px solid var(--border);
      border-radius: 999px;
      padding: 0.4rem 0.8rem;
      font-size: 0.82rem;
      font-weight: 700;
    }

    .carousel-shell {
      margin-top: 1.6rem;
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      padding: 1rem;
      box-shadow: var(--shadow-soft);
    }

    .carousel-head {
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 1rem;
      margin-bottom: 0.9rem;
    }

    .carousel-controls { display: flex; gap: 0.6rem; }

    .arrow-btn {
      width: 2.8rem;
      height: 2.8rem;
      border-radius: 999px;
      border: 1px solid var(--border);
      background: white;
      color: var(--primary-deep);
      font-size: 1.25rem;
      font-weight: 700;
      cursor: pointer;
      transition: transform 180ms ease, background 200ms ease;
    }

    .arrow-btn:hover,
    .arrow-btn:focus-visible {
      background: color-mix(in oklch, var(--accent) 38%, white 62%);
      transform: translateY(-1px);
    }

    .carousel-track-wrap {
      overflow: hidden;
      border-radius: var(--radius-md);
    }

    .carousel-track {
      display: flex;
      gap: 1rem;
      transition: transform 420ms cubic-bezier(0.22, 1, 0.36, 1);
      will-change: transform;
    }

    .product-card {
      flex: 0 0 calc((100% - 2rem) / 3);
      background: white;
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      overflow: hidden;
      box-shadow: 0 3px 10px color-mix(in oklch, black 6%, transparent);
    }

    .product-card img {
      width: 100%;
      aspect-ratio: 4 / 3;
      object-fit: cover;
    }

    .product-body { padding: 0.9rem; }
    .product-name { margin: 0; font-size: 1rem; }
    .product-price {
      margin: 0.45rem 0 0;
      color: var(--primary-deep);
      font-weight: 700;
      font-size: 1rem;
    }

    .stats-banner {
      margin: 1rem 0 0;
      padding: 1.2rem;
      border-radius: var(--radius-lg);
      background: linear-gradient(120deg, color-mix(in oklch, var(--primary) 85%, white 15%), color-mix(in oklch, var(--accent) 62%, white 38%));
      color: color-mix(in oklch, white 94%, var(--text) 6%);
      box-shadow: var(--shadow-soft);
    }

    .stats-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 1rem;
    }

    .stat-card {
      border-radius: 0.95rem;
      background: color-mix(in oklch, white 16%, transparent);
      border: 1px solid color-mix(in oklch, white 26%, transparent);
      padding: 0.95rem;
    }

    .stat-value {
      font-family: "Nunito", sans-serif;
      font-size: clamp(1.4rem, 3vw, 2rem);
      margin: 0;
      line-height: 1;
      font-weight: 800;
    }

    .stat-label {
      margin: 0.4rem 0 0;
      font-size: 0.92rem;
      color: color-mix(in oklch, white 88%, var(--text) 12%);
    }

    .seasonal-grid,
    .category-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 1rem;
      margin-top: 1.4rem;
    }

    .seasonal-card,
    .category-card {
      position: relative;
      border-radius: var(--radius-md);
      overflow: hidden;
      box-shadow: var(--shadow-soft);
      border: 1px solid var(--border);
      background: #fff;
    }

    .seasonal-card img,
    .category-card img {
      width: 100%;
      aspect-ratio: 4/3;
      object-fit: cover;
    }

    .seasonal-info {
      padding: 0.9rem;
      background: white;
    }

    .seasonal-info h3 { margin: 0; font-size: 1.05rem; }
    .seasonal-info p { margin: 0.35rem 0 0; color: var(--muted); font-size: 0.95rem; }

    .category-card {
      transform: scale(1);
      transition: transform 210ms ease, box-shadow 250ms ease;
    }

    .category-card:hover,
    .category-card:focus-within {
      transform: scale(1.03);
      box-shadow: 0 16px 28px color-mix(in oklch, black 14%, transparent);
    }

    .category-overlay {
      position: absolute;
      inset: 0;
      display: flex;
      align-items: end;
      padding: 1rem;
      background: linear-gradient(180deg, transparent 35%, color-mix(in oklch, var(--text) 45%, transparent) 100%);
      color: white;
      opacity: 0;
      transition: opacity 220ms ease;
    }

    .category-card:hover .category-overlay,
    .category-card:focus-within .category-overlay {
      opacity: 1;
    }

    .category-overlay span {
      font-family: "Nunito", sans-serif;
      font-weight: 800;
      font-size: 1.15rem;
    }

    .store-card,
    .newsletter-card {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      padding: clamp(1rem, 3vw, 2rem);
      box-shadow: var(--shadow-soft);
    }

    .search-row,
    .newsletter-row {
      margin-top: 1rem;
      display: flex;
      gap: 0.7rem;
      flex-wrap: wrap;
    }

    input[type="text"],
    input[type="email"] {
      flex: 1 1 260px;
      min-height: 46px;
      border-radius: 0.8rem;
      border: 1px solid var(--border);
      padding: 0.75rem 0.9rem;
      font-size: 1rem;
      background: white;
      color: var(--text);
    }

    input:focus-visible {
      outline: 2px solid color-mix(in oklch, var(--primary) 60%, white 40%);
      outline-offset: 1px;
    }

    .results {
      margin-top: 1rem;
      display: none;
      overflow-x: auto;
    }

    .results.show { display: block; }

    table {
      border-collapse: collapse;
      width: 100%;
      min-width: 680px;
      background: white;
      border-radius: 0.8rem;
      overflow: hidden;
    }

    th, td {
      text-align: left;
      padding: 0.8rem;
      border-bottom: 1px solid var(--border);
      font-size: 0.95rem;
    }

    th {
      background: color-mix(in oklch, var(--surface-2) 80%, white 20%);
      color: var(--text);
      font-family: "Nunito", sans-serif;
    }

    .confirmation {
      margin-top: 0.8rem;
      padding: 0.7rem 0.85rem;
      border-radius: 0.75rem;
      border: 1px solid color-mix(in oklch, var(--primary) 35%, white 65%);
      color: var(--primary-deep);
      background: color-mix(in oklch, var(--accent) 22%, white 78%);
      display: none;
      font-weight: 600;
    }

    .confirmation.show { display: inline-block; }

    footer {
      padding: 3rem 0 2rem;
      background: color-mix(in oklch, var(--surface-2) 72%, white 28%);
      border-top: 1px solid var(--border);
      margin-top: 2rem;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 1rem;
    }

    .footer-col h3 { margin: 0 0 0.8rem; font-size: 1rem; }
    .footer-col a {
      display: block;
      padding: 0.2rem 0;
      color: var(--muted);
      transition: color 180ms ease;
      font-size: 0.95rem;
    }

    .footer-col a:hover,
    .footer-col a:focus-visible { color: var(--primary-deep); }

    .footer-tagline {
      margin-top: 1.2rem;
      color: var(--muted);
      font-size: 0.92rem;
      border-top: 1px dashed var(--border);
      padding-top: 0.9rem;
    }

    @media (max-width: 1023px) {
      .product-card { flex-basis: calc((100% - 1rem) / 2); }
      .stats-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
      .seasonal-grid,
      .category-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
      .hero-grid { grid-template-columns: 1fr; }
    }

    @media (max-width: 760px) {
      .section { padding: 3.2rem 0; }
      .header-inner { flex-wrap: wrap; padding: 0.8rem 0; }
      nav { width: 100%; }
      nav ul { justify-content: space-between; }
      .product-card { flex-basis: 100%; }
      .seasonal-grid,
      .category-grid,
      .footer-grid,
      .stats-grid { grid-template-columns: 1fr; }
      table { min-width: 560px; }
    }
  </style>
</head>
<body>
  <header class="site-header">
    <div class="container header-inner">
      <a class="brand" href="#home" aria-label="Fresh Pantry Home">
        <span class="brand-badge" aria-hidden="true">🥬</span>
        Fresh Pantry
      </a>
      <nav aria-label="Primary navigation">
        <ul>
          <li><a class="nav-link" href="#featured-products">Products</a></li>
          <li><a class="nav-link" href="#store-locator">Our Stores</a></li>
          <li><a class="nav-link" href="#seasonal-picks">Recipes</a></li>
          <li><a class="nav-link" href="#footer">About Us</a></li>
        </ul>
      </nav>
    </div>
  </header>

  <main id="home">
    <section class="section" aria-labelledby="hero-title">
      <div class="container hero-grid">
        <div>
          <h1 id="hero-title" class="hero-title">Discover Everyday Deliciousness</h1>
          <p class="hero-copy">
            Fresh Pantry is your neighborhood grocery destination for unique, high-quality food finds at prices that make every cart feel like a win.
          </p>
          <div class="actions">
            <a class="btn btn-primary" href="#featured-products">Explore Products</a>
            <a class="btn btn-secondary" href="#store-locator">Find a Store</a>
          </div>
        </div>
        <article class="hero-card" aria-label="Featured in-store experience image">
          <img src="https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&w=1000&h=1200&q=80" alt="Colorful grocery shelves with produce and pantry items" />
          <span class="hero-chip">New Finds Every Week ✨</span>
        </article>
      </div>
    </section>

    <section id="featured-products" class="section" aria-labelledby="featured-title">
      <div class="container">
        <h2 id="featured-title" class="section-title">Featured Products</h2>
        <p class="section-subtitle">Fan-favorite pantry picks with big flavor and even better value.</p>

        <div class="carousel-shell" role="region" aria-label="Featured products carousel">
          <div class="carousel-head">
            <strong>Swipe-worthy shelf stars</strong>
            <div class="carousel-controls">
              <button class="arrow-btn" id="prevBtn" aria-label="Show previous products">←</button>
              <button class="arrow-btn" id="nextBtn" aria-label="Show next products">→</button>
            </div>
          </div>
          <div class="carousel-track-wrap">
            <div class="carousel-track" id="productTrack">
              <article class="product-card">
                <img src="https://images.unsplash.com/photo-1515003197210-e0cd71810b5f?auto=format&fit=crop&w=900&h=700&q=80" alt="Organic Maple Granola in a bowl" />
                <div class="product-body">
                  <h3 class="product-name">Organic Maple Granola</h3>
                  <p class="product-price">$4.99</p>
                </div>
              </article>
              <article class="product-card">
                <img src="https://images.unsplash.com/photo-1511690743698-d9d85f2fbf38?auto=format&fit=crop&w=900&h=700&q=80" alt="Everything But The Bagel Seasoning jar with spices" />
                <div class="product-body">
                  <h3 class="product-name">Everything But The Bagel Seasoning</h3>
                  <p class="product-price">$2.49</p>
                </div>
              </article>
              <article class="product-card">
                <img src="https://images.unsplash.com/photo-1571115764595-644a1f56a55c?auto=format&fit=crop&w=900&h=700&q=80" alt="Dark chocolate peanut butter cups on a plate" />
                <div class="product-body">
                  <h3 class="product-name">Dark Chocolate Peanut Butter Cups</h3>
                  <p class="product-price">$3.99</p>
                </div>
              </article>
              <article class="product-card">
                <img src="https://images.unsplash.com/photo-1551892374-ecf8754cf8b0?auto=format&fit=crop&w=900&h=700&q=80" alt="Cauliflower gnocchi ready to cook" />
                <div class="product-body">
                  <h3 class="product-name">Cauliflower Gnocchi</h3>
                  <p class="product-price">$2.99</p>
                </div>
              </article>
              <article class="product-card">
                <img src="https://images.unsplash.com/photo-1604908176997-125f25cc6f3d?auto=format&fit=crop&w=900&h=700&q=80" alt="Mandarin orange chicken with rice" />
                <div class="product-body">
                  <h3 class="product-name">Mandarin Orange Chicken</h3>
                  <p class="product-price">$4.49</p>
                </div>
              </article>
            </div>
          </div>
        </div>

        <div class="stats-banner" aria-label="Brand highlights">
          <div class="stats-grid">
            <article class="stat-card">
              <p class="stat-value">500+</p>
              <p class="stat-label">Stores Nationwide</p>
            </article>
            <article class="stat-card">
              <p class="stat-value">4,000+</p>
              <p class="stat-label">Unique Products</p>
            </article>
            <article class="stat-card">
              <p class="stat-value">80%</p>
              <p class="stat-label">Private Label Items</p>
            </article>
            <article class="stat-card">
              <p class="stat-value">Weekly</p>
              <p class="stat-label">New Items Every Week</p>
            </article>
          </div>
        </div>
      </div>
    </section>

    <section id="seasonal-picks" class="section" aria-labelledby="seasonal-title">
      <div class="container">
        <h2 id="seasonal-title" class="section-title">Seasonal Picks</h2>
        <p class="section-subtitle">Fresh flavors for your current cravings — from weeknight comfort to weekend treats.</p>
        <div class="seasonal-grid">
          <article class="seasonal-card">
            <img src="https://images.unsplash.com/photo-1512621776951-a57141f2eefd?auto=format&fit=crop&w=900&h=700&q=80" alt="Fresh spring salad ingredients" />
            <div class="seasonal-info">
              <h3>Spring Crunch Salad Kit</h3>
              <p>Crisp greens, sweet citrus, and nutty toppings.</p>
            </div>
          </article>
          <article class="seasonal-card">
            <img src="https://images.unsplash.com/photo-1467003909585-2f8a72700288?auto=format&fit=crop&w=900&h=700&q=80" alt="Roasted vegetables and herbs on tray" />
            <div class="seasonal-info">
              <h3>Garden Herb Roasting Pack</h3>
              <p>Colorful veggies and aromatic herb blends.</p>
            </div>
          </article>
          <article class="seasonal-card">
            <img src="https://images.unsplash.com/photo-1482049016688-2d3e1b311543?auto=format&fit=crop&w=900&h=700&q=80" alt="Berry yogurt breakfast bowl" />
            <div class="seasonal-info">
              <h3>Berry Sunrise Breakfast Box</h3>
              <p>Fruit-forward mornings with creamy goodness.</p>
            </div>
          </article>
        </div>
      </div>
    </section>

    <section id="categories" class="section" aria-labelledby="categories-title">
      <div class="container">
        <h2 id="categories-title" class="section-title">Browse by Category</h2>
        <p class="section-subtitle">Hover to peek inside each aisle favorite.</p>
        <div class="category-grid">
          <article class="category-card" tabindex="0" aria-label="Snacks and Sweets category">
            <img src="https://images.unsplash.com/photo-1599490659213-e2b9527bd087?auto=format&fit=crop&w=900&h=700&q=80" alt="Snacks and sweets assortment" />
            <div class="category-overlay"><span>Snacks &amp; Sweets</span></div>
          </article>
          <article class="category-card" tabindex="0" aria-label="Fresh Produce category">
            <img src="https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&w=900&h=700&q=80" alt="Fresh produce display" />
            <div class="category-overlay"><span>Fresh Produce</span></div>
          </article>
          <article class="category-card" tabindex="0" aria-label="Frozen Favorites category">
            <img src="https://images.unsplash.com/photo-1612874742237-6526221588e3?auto=format&fit=crop&w=900&h=700&q=80" alt="Frozen meal selections" />
            <div class="category-overlay"><span>Frozen Favorites</span></div>
          </article>
          <article class="category-card" tabindex="0" aria-label="Beverages category">
            <img src="https://images.unsplash.com/photo-1497534446932-c925b458314e?auto=format&fit=crop&w=900&h=700&q=80" alt="Beverages and juices lineup" />
            <div class="category-overlay"><span>Beverages</span></div>
          </article>
          <article class="category-card" tabindex="0" aria-label="Dairy and Cheese category">
            <img src="https://images.unsplash.com/photo-1628088062854-d1870b4553da?auto=format&fit=crop&w=900&h=700&q=80" alt="Dairy and cheese products" />
            <div class="category-overlay"><span>Dairy &amp; Cheese</span></div>
          </article>
        </div>
      </div>
