  <script>
    (function () {
      const track = document.getElementById('productTrack');
      const cards = Array.from(track.children);
      const prevBtn = document.getElementById('prevBtn');
      const nextBtn = document.getElementById('nextBtn');
      let currentIndex = 0;

      function cardsPerView() {
        if (window.innerWidth <= 760) return 1;
        if (window.innerWidth <= 1023) return 2;
        return 3;
      }

      function maxIndex() {
        return Math.max(0, cards.length - cardsPerView());
      }

      function updateCarousel() {
        const firstCardWidth = cards[0].getBoundingClientRect().width;
        const gap = 16;
        const offset = currentIndex * (firstCardWidth + gap);
        track.style.transform = `translateX(-${offset}px)`;
        prevBtn.disabled = currentIndex === 0;
        nextBtn.disabled = currentIndex >= maxIndex();
        prevBtn.style.opacity = prevBtn.disabled ? '0.5' : '1';
        nextBtn.style.opacity = nextBtn.disabled ? '0.5' : '1';
      }

      prevBtn.addEventListener('click', () => {
        currentIndex = Math.max(0, currentIndex - 1);
        updateCarousel();
      });

      nextBtn.addEventListener('click', () => {
        currentIndex = Math.min(maxIndex(), currentIndex + 1);
        updateCarousel();
      });

      window.addEventListener('resize', () => {
        currentIndex = Math.min(currentIndex, maxIndex());
        updateCarousel();
      });

      updateCarousel();

      const zipInput = document.getElementById('zipInput');
      const searchBtn = document.getElementById('searchBtn');
      const storeResults = document.getElementById('storeResults');

      function handleStoreSearch() {
        const zip = zipInput.value.trim();
        if (/^\d{5}$/.test(zip)) {
          storeResults.classList.add('show');
        } else {
          storeResults.classList.remove('show');
          zipInput.focus();
        }
      }

      searchBtn.addEventListener('click', handleStoreSearch);
      zipInput.addEventListener('keydown', (event) => {
        if (event.key === 'Enter') handleStoreSearch();
      });

      const emailInput = document.getElementById('emailInput');
      const subscribeBtn = document.getElementById('subscribeBtn');
      const subscribeConfirmation = document.getElementById('subscribeConfirmation');

      function handleSubscribe() {
        const email = emailInput.value.trim();
        if (/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
          subscribeConfirmation.classList.add('show');
          emailInput.value = '';
        } else {
          subscribeConfirmation.classList.remove('show');
          emailInput.focus();
        }
      }

      subscribeBtn.addEventListener('click', handleSubscribe);
      emailInput.addEventListener('keydown', (event) => {
        if (event.key === 'Enter') handleSubscribe();
      });
    })();
  </script>
